mapper.select:
SELECT m.material_id, m.course_id, c.title AS course_title, m.title, m.material_type, m.file_path, m.file_size, m.uploaded_by, a.full_name AS uploader_name, m.created_at FROM material m LEFT JOIN course c ON m.course_id = c.course_id LEFT JOIN account a ON m.uploaded_by = a.account_id WHERE 1 = 1
AND m.course_id = #{courseId}
AND m.material_type = #{materialType}
AND m.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY m.created_at DESC
